/* ======================= 6. ИСПОЛНЕНИЕ И ЗАКРЫТИЕ ======================= */
function sapExec() {
  const ch = [["ДЕБЛ", "проводки разрешены"], ["ПДТВ / ЧПДТ", "трудозатраты ХС подтверждены (IW41)"], ["MIGO", "списание МТР (МОЛ)"], ["ПРНТ", "работы подрядчика приняты (для УСО)"], ["ФХСМ", "затрат больше не будет"], ["ТЗКР", "техническое закрытие"], ["ПРСЗ / НПСЗ", "служба заказчика БЕ"], ["ВСБЕ", "выручка, ZMM_370"], ["ЗАКР", "сальдо = 0"]];
  const b = ch.map((c, i) => SM.box(8 + i * 99, 14, 90, 70, c[0], c[1], c[0] === "ТЗКР" ? "a" : i > 5 ? "i" : "n", { max: 14 }) + (i < ch.length - 1 ? SM.arrow(98 + i * 99, 49, 106 + i * 99, 49) : "")).join("");
  const ctl = D.controlRows || [];
  const y = String(new Date().getFullYear());
  const rel = ctl.filter(r => r.y === y && r.stage === "released"), fd = ctl.filter(r => r.y === y && r.stage === "factDone");
  const sum = a => a.reduce((s, r) => s + (r.planCounted || r.p + r.up || 0), 0);
  return `
    ${smCard("Цепочка исполнения и закрытия", `${SM.svg(900, 100, b, "Цепочка закрытия")}
      <p>Для работ АО «Развитие» добавлен шаг приёмки службой заказчика БЕ: ПРСЗ или НПСЗ. ПРНТ/НПРН и ПРСЗ/НПСЗ взаимоисключающие —
        при установке одного система снимает другой. ФХСМ означает, что затрат больше не ожидается и заказ готов к ТЗКР (памятка ТОиР-84).</p>
      ${ctl.length ? `<div class="kpis">${kpi(`Деблокированы без факта (${y})`, num(rel.length) + ` <small>${mrub(sum(rel))}</small>`, rel.length ? "warn" : "good")}${kpi(`Факт проведён, не ТЗКР (${y})`, num(fd.length) + ` <small>${mrub(sum(fd))}</small>`, fd.length ? "warn" : "good")}</div><p class="hint">Заказы WK из витрины «Контроль отделов»; разбор — там же, «Исполнение».</p>` : ""}`)}
    ${smCard("Что проверяет система", `<div class="twrap"><table><thead><tr><th>Действие</th><th>Условие</th><th>Если нарушено</th></tr></thead><tbody>
      ${[["Поставить ПРНТ", "заказ деблокирован (ДЕБЛ)", "статус не ставится"], ["Технически закрыть (ТЗКР)", "есть ПРНТ (для заказов с УСО) или ПДТВ/ЧПДТ (с ФОТ); нет НПРН", "закрыть нельзя"], ["Поставить ПРСЗ / НПСЗ", "заказ в ТЗКР, роль «Специалист службы заказчика БЕ»", "статус не ставится"],
        ["После ПРСЗ", "запрещены счета (RMRP), подтверждения (RMRU, RMPH), списание МТР (RMWA), акты подрядчика (RMWE)", "проводка отклоняется"], ["Снять ПРСЗ", "только руководитель службы заказчика БЕ и только до ВСБЕ", "после ВСБЕ — ошибка"],
        ["ТЗКР с отклонением от бизнес-плана", "отклонение факта МТР или фиксированного УСО от БП выше допустимого", "нужно указать причину (анализ — ZPM_RCH)"], ["Блокировка сроков ZPM_DATE_BLOCK", "период по БЕ, заводу, группе, ТМ, ЕО", "нельзя менять сроки, простой и закрывать заказ"]]
        .map(r => `<tr><td>${r[0]}</td><td>${esc(r[1])}</td><td>${esc(r[2])}</td></tr>`).join("")}</tbody></table></div>
      <p class="hint">При сохранении — предупреждения: МТР подрядчика не сходятся с услугой по плану или факту; при ТЗКР счета по УСО проведены не полностью; ОС заказа ≠ ОС единицы оборудования.</p>
      ${smSrc("памятки ТОиР-77, ТОиР-84, ТОиР-72, ТОиР-96; «Памятка по контролю отражения факта на заказы ТОРО»; КД ERP.13.9.2.55.")}`)}
    ${smCard("Контроль закрытия в IW38", `${smList(["IW38 → формат «CONTROL — контроль заказов», своё ТМ, базисное окончание = вчера; фильтры «Нет подтверждения работ» и «Нет списания МТР»", "<b>Статус отражения факта</b>: код = полнота + категория затрат (ХС, работы подрядчика, списание МТР, счёт-фактура УСО, счёт по МТР подрядчика), например 1Н-СМ — списание МТР не проведено", "<b>Статус периода проводок</b> — проводки вне базисных сроков по каждой категории", "<b>Статус приёмки</b>: #ТЗКР — всё проведено, пора закрывать; #ПРСЗ — пора принять службой заказчика; заказ блокирует выручку", "Отчёт CONTROL — не реже раза в неделю для инженеров ТОиР и руководителей; при большом объёме отключайте «Дополнительные поля»"])}
      <p><b>Отменили работу</b> — закройте заказ и пометьте на удаление или перенесите сроки: деблокированный заказ без факта искажает исполнение программы. Удаляя законтрактованные МТР, проверьте НВСО.</p>`)}
    ${smCard("Чек-лист планировщика", `<div class="sm-grid2"><div><b>Каждую неделю</b>${smList(["IW38 CONTROL: нет подтверждений, нет списаний МТР", "Деблокированные без факта: провести, перенести или закрыть", "Заказы следующей недели на согласовании (СГПЛ)", "Активные ЗНК к своим заказам обработаны", "СРОЧ: есть ли покрытие к дате работ"])}</div>
      <div><b>Каждый месяц</b>${smList(["Заказы с ФХСМ технически закрыты (ТЗКР)", "Статус приёмки: #ТЗКР и #ПРСЗ отработаны", "Прогноз завершения месяца (ПЗТМ) согласован", "План-график следующего месяца: МЕС → УТВМ", "Удаления МТР не создали лишних НВСО"])}</div></div>
      ${smSrc("методичка «SAP ТОРО для планировщика» (чек-лист), регламент «Выполнение программы ППА, фактический учёт воздействий».")}`)}`;
}

/* ======================= 7. БЮДЖЕТИРОВАНИЕ ======================= */
function sapBudget() {
  const fl = ["Бюджетные ориентиры УК (планировщик бюджета УК)", "Согласование ориентиров: тех. директор УК и вице-президент БПиТП", "Структура СПП-элементов на год (статус АКТС)", "Годовой бюджет ППА из заказов (ГОД, ПЗТГ)", "Согласование в SAP MCB по шагам (ТОиР-90)", "ТК БЕ → БК/ИК УК → утверждение (УТВА на СПП, ТКБЕ/УТВП на заказах)", "Исполнение, прогнозы ПЗТМ/ПЗТГ", "Корректировка лимита: ТРКБ → заявка → КОРБ / ОТКБ"];
  const b = fl.map((t, i) => { const r = Math.floor(i / 4), c = r ? 3 - (i % 4) : i % 4, x = 10 + c * 222, y = 12 + r * 100; return SM.box(x, y, 200, 70, t, "", i === 5 ? "a" : i === 7 ? "w" : "n", { max: 30, bold: false }) + (i < fl.length - 1 ? (i === 3 ? SM.arrow(x + 100, y + 70, x + 100, y + 98) : r === 0 ? SM.arrow(x + 200, y + 35, x + 220, y + 35) : SM.arrow(x, y + 35, x - 20, y + 35)) : ""); }).join("");
  const f = sapFlagCounts(["2026", "2027"]);
  return `
    ${smCard("Как формируется и исполняется бюджет ППА", `${SM.svg(900, 190, b, "Бюджетный цикл ППА")}
      <p>Бюджет воздействий на ПА планируется на СПП-элементах (структурный план проекта): заказ ТОРО присваивается СПП-элементу с выделенным
        лимитом. Годовой бюджет собирается из заказов годовой программы и согласуется в <b>SAP MCB</b>; утверждённые показатели передаются в
        АСКБ/АСКИ, на СПП ставится «УТВА», на заказы — ТКБЕ и УТВП.</p>
      ${smSrc("регламент «Планирование, исполнение, корректировка и контроль бюджета ППА» (ПП-07.04); КД ERP.13.9.2.51 «Формирование и управление бюджетами ТОиР».")}`)}
    ${smCard("Согласование бюджета ТОиР в MCB", `<div class="twrap"><table><thead><tr><th>Шаг</th><th>Функциональная роль (пример АО «Полюс Вернинское»)</th></tr></thead><tbody>
      ${[["1. Проверка специалистом по бюджетированию и отчётности БЕ УПА", "Планировщик бюджета УА АО «Развитие»"], ["2a. Главный механик по стационарному оборудованию", "Главный специалист ТОиР АО «Развитие»"], ["2b. Главный механик по самоходному оборудованию", "Главный специалист ТОиР АО «Развитие»"], ["2c. Главный энергетик", "Главный специалист ТОиР БЕ"], ["2d. Начальник отдела планирования УПА", "Старший планировщик ТОиР АО «Развитие»"],
        ["3. Директор по УПА (ТК БЕ)", "Согласующий ТК АО «Развитие» и ТК БЕ"], ["3a–c. Начальник управления планирования и контроля, операционный директор УПА, главный энергетик УК", "УК Главный специалист ТОиР"], ["4. После внесистемного согласования БК/ИК УК — начальник управления РМАиО", "УК Согласующий технического комитета"]]
        .map(r => `<tr><td>${esc(r[0])}</td><td>${esc(r[1])}</td></tr>`).join("")}</tbody></table></div>
      <p class="hint">Шаги сопоставлены группам планирования и центрам затрат: механик по самоходному оборудованию видит только свои МВЗ.</p>${smSrc("памятка ТОиР-90 «Согласование бюджета ТОиР в MCB» (2024).")}`)}
    ${smCard("Корректировка лимита и контроль", `<div class="sm-grid2"><div>${smList(["Не хватает лимита по СПП — на заказе <b>ТРКБ</b> (требуется корректировка)", "Заявка на корректировку → анализ главным специалистом → решение: за счёт резерва УО или резерва УК / без источника (технический комитет, тех. директор УК)", "Итог: <b>КОРБ</b> (выделен и скорректирован) или <b>ОТКБ</b> (отклонено) — автоматически", "Сроки реакции: 1 рабочий день на служебную записку и после согласования, 2 дня после ТРКБ, 3 дня на проверку бюджета в MCB"])}</div>
      <div>${smList(["Прогнозы: <b>ПЗТГ</b> — воздействие в прогнозе завершения года, <b>ПЗТМ</b> — месяца (срез КТГ)", "При ТЗКР система сравнивает факт МТР и фиксированного УСО с версией бизнес-плана; при превышении допустимого отклонения — причина обязательна (IW38/IW39 «Данные бизнес-плана», отчёт ZPM_RCH)", "Метрики: доля повторяющихся корректировок, доля согласованных заявок на корректировку"])}</div></div>
      <p>Заказы WK 2026–2027 со статусами бюджета: ${["ТКБЕ", "ТРКБ", "КОРБ", "ОТКБ", "СГЛБ", "ПЗТГ", "ПЗТМ"].map(k => `<span class="badge">${k} ${num(f.c[k] || 0)}</span>`).join(" ")}
        <span class="hint">(только коды, которые витрина «Контроль отделов» хранит в признаках заказа)</span></p>
      ${smSrc("регламент ПП-07.04 (таблицы 16–21), памятка ТОиР-96 «Отклонение затрат по МТР, УСО от бизнес-плана».")}`)}
    ${smCard("Итерации прогноза бюджета ремонтов", `<p>Три итерации — прогноз 3+9, 6+6, 8+4 с защитой на бюджетном комитете 15 мая, 15 августа и 15 октября; подробно — ${sapGo("plan", "Планирование")}.
      Бюджет на следующий год начинают прогнозировать в марте, окончательно согласованную версию передают на утверждение в октябре.</p>`)}`;
}

/* ======================= 8. НАДЁЖНОСТЬ И КТГ ======================= */
function sapRel() {
  // матрица рисков 5×5: значимость = вероятность × последствия
  let mx = "";
  for (let p = 1; p <= 5; p++) for (let c = 1; c <= 5; c++) {
    const s = p * c, k = s >= 15 ? "b" : s >= 8 ? "w" : "g";
    mx += `<rect class="sm-rm ${k}" x="${70 + (c - 1) * 62}" y="${20 + (5 - p) * 44}" width="58" height="40" rx="5"/><text class="sm-bt" x="${70 + (c - 1) * 62 + 29}" y="${20 + (5 - p) * 44 + 21}" text-anchor="middle" dominant-baseline="middle">${s}</text>`;
  }
  mx += `<text class="sm-h2" x="225" y="250" text-anchor="middle">Последствия отказа (1–5)</text>` + `<text class="sm-h2" transform="rotate(-90 22 130)" x="22" y="130" text-anchor="middle">Вероятность (1–5)</text>`;
  const fleet = D.fleet && D.fleet.units ? D.fleet.units : [];
  const avg = k => { const v = fleet.map(u => u[k]).filter(Number.isFinite); return v.length ? v.reduce((s, x) => s + x, 0) / v.length : null; };
  return `
    ${smCard("Критичность оборудования", `<div class="sm-grid2"><div>${SM.svg(400, 262, mx, "Матрица рисков 5×5", 360)}</div>
      <div><p>Критичность ПА — сочетание вероятности отказа и тяжести последствий (жизнь и здоровье, окружающая среда, выпуск продукции,
        финансы). Значимость риска = вероятность × последствия по шкале 5×5 (например, 15 = 3 × 5). По ней оборудование делят на категории:</p>
        ${smList(["<b>A</b> — жизненно важное: отказ угрожает жизни и здоровью, большие экологические и финансовые последствия", "<b>B</b> — отказ значительно влияет на ОТ, ПБ, экологию и выпуск продукции", "<b>C</b> — существенно не влияет на выпуск продукции, ОТ, ПБ и ООС"])}
        <p>Уровни анализа: система активов (отделение измельчения) → актив, ЕО (шаровая мельница) → компонент (электродвигатель, редуктор, смазка) —
          для сложных критичных активов, чтобы задать разные стратегии узлам. Критичность пересматривают периодически и при изменении режима,
          технологии, вводе оборудования, КР и модернизации.</p></div></div>
      ${smSrc("курс «1.2 Система ТОиР…», часть 2 «Критичность ПА»; процесс ПП-07.02.02. Пороги категорий A/B/C — в методике ранжирования Компании, здесь не приводятся.")}`)}
    ${smCard("Виды воздействий и стратегии ТОиР", `<div class="sm-grid2"><div><b>Виды воздействий</b>${smList(["<b>ЕТО</b> — ежесменное техническое обслуживание (эксплуатация; профиль PM_ETO, статус ЗАПЛ)", "<b>ТО</b> — техническое обслуживание по регламенту: смазка, регулировка, замена фильтров", "<b>ТР</b> — текущий ремонт: замена и восстановление изношенных деталей и узлов", "<b>КР</b> — капитальный ремонт: восстановление ресурса; может быть капитализируемым (КРМТ, CAPEX)"])}</div>
      <div><b>Стратегии</b>${smList(["<b>Планово-предупредительная</b> (базовая): по календарю или по наработке — пакеты мероприятий стратегии, техкарты и планы ППР", "<b>По состоянию</b>: работы назначаются по результатам диагностики и мониторинга (заказы ATS1)", "<b>По отказу</b>: допустима для некритичного оборудования с низким риском; нужен график ЕТО/ТО и аварийный запас", "Стратегию разрабатывает надёжность; планировщик должен понимать, по какой стратегии и почему назначено воздействие"])}</div></div>
      ${smSrc("курс 1.2, часть 4 «Виды и стратегии ТОиР»; «57_ТОиР_Ведение БДН и планов ТОРО».")}`)}
    ${smCard("КТГ — коэффициент технической готовности", `<p class="sm-formula">КТГ = (календарный фонд времени − время ремонтного простоя) / календарный фонд времени</p>
      ${smList(["<b>Плановый КТГ</b> — требуемая готовность: учитывает простои по годовому план-графику; согласуется в годовом планировании и передаётся в ПТО (11-П, 12-П)", "<b>Фактический КТГ</b> — по фактическим простоям, включая внеплановые; учитывается причина простоя (техническая или технологическая)", "Простои регистрируются сообщениями с сегментами ремонтного простоя (памятка ТОиР-61); изменения фактических ремонтных простоев после закрытия периода запрещены", "Срезы согласования КТГ по парку и по классу — памятка ТОиР-74; прогноз завершения месяца — ПЗТМ"])}
      ${fleet.length ? `<div class="kpis">${kpi("КТГ план, парк WK", pct(avg("ktg")))}${kpi("КТГ факт, парк WK", pct(avg("kio")), avg("kio") < avg("ktg") ? "warn" : "good")}</div><p class="hint">Среднее по бортам витрины «Парк» (TOPO ktg.json).</p>` : ""}
      ${smSrc("курс 1.2, часть 3 «КТГ»; «Методические указания Компании. Методика расчёта КТГ»; памятки ТОиР-61, ТОиР-74.")}`)}
    ${smCard("Техническое состояние: сообщения, измерения, диагностика, ОТС", `<div class="sm-grid2">
      <div><b>Регистрация состояния (сообщения ТОРО)</b>${smList(["Инициатор, оператор или специалист диагностики (ЛНК) создаёт сообщение о дефекте, отказе, простое (IW21)", "Координатор рассматривает и передаёт в работу; инженер по надёжности принимает окончательное решение и закрывает", "В сообщении — причина отказа и вид дефекта из каталогов кодов: основа анализа коренных причин", "Виды сообщений различают регистрацию дефекта, консервацию (A4/A5) и т. п."])}</div>
      <div><b>Измерения и диагностика</b>${smList(["Точки измерения на ЕО/ТМ: наработка, моточасы, температура; документы измерений (IK11) — по ним работают планы по наработке", "Специалист по вводу параметров регистрирует показания, инженер ТОиР контролирует", "Диагностику выполняет ЛНК или подрядчик; по результатам — решение об останове (главный инженер, координатор), сообщение и заказ; инженер ТОиР принимает акты", "<b>ОТС</b> — оценка технического состояния: инженер ТОиР определяет значение по данным, главный специалист согласует; ОТС уточняет сроки в годовой программе"])}</div></div>
      ${smSrc("регламенты «Регистрация технического состояния», «Регистрация параметров эксплуатации», «Регистрация результатов диагностики», «Анализ значений оценки технического состояния»; КД ERP.13.9.2.56.")}`)}`;
}

/* ======================= 9. МТР И РЕСУРСЫ ======================= */
function sapMtr() {
  return `
    ${smCard("Когда закупка видит потребность: «Резерв./заявка»", `${smList(["<b>Немедленно</b> — компонент сразу попадает в планирование потребности (ППМ)", "<b>Начиная с деблокирования</b> — только после ДЕБЛ: поздний деблок = поздняя закупка; деблокируйте с запасом на срок поставки", "<b>Никогда</b> — в заявку не попадёт; ставится автоматически справочным позициям и движениям оборотного фонда с неисправной партией; покрыть может только склад"])}
      <p>Вкладка «Обеспеченность» показывает признак по строкам заказов WK и сколько потребности закупка ещё не видит.</p>${smSrc("методичка «SAP ТОРО для планировщика»; КД ERP.13.9.2.57 «Ресурсное обеспечение ТОиР».")}`)}
    ${smCard("Срочность (СРОЧ) и невостребованные остатки (НВСО)", `<div class="sm-grid2"><div><b>СРОЧ</b>${smList(["Позиция срочная, если сегодня + срок поставки + срок согласования > дата потребности и свободных остатков не хватает", "Остатки — с перевалочной базой и прямыми аналогами, без запасов проектов", "Не передана в ППМ — снимается, когда остатков хватает; передана — только по сроку", "Проверки — при сохранении заказа по ночному срезу ППМ; вручную — «ФОНОВЫЙ пересчёт заказов ТОРО» в IW38"])}</div>
      <div><b>НВСО</b>${smList(["Удаление, сокращение или перенос законтрактованной потребности сравнивается с потребностью на 2 года и запасом + спецификациями к договору", "Профицит текущего года — предупреждение; следующего — ошибка: удалить может главный специалист ТОиР УК", "Перед сокращением: ZMM_MRP_MAINT (NVSO_SVERKA, NVSO_ZNPSKL), склад — MB52", "После удаления или ТЗКР с отказом ставится НВСО — его не снять"])}</div></div>
      ${smSrc("памятки ТОиР-75, ТОиР-86, ТОиР-96 «Оптимизация проверок СРОЧ/НВСО».")}`)}
    ${smCard("Аналоги, оборотный фонд, АТЗ, МТР подрядчика", `<div class="sm-grid2">
      <div><b>Аналоги</b>${smList(["<b>Прямой</b> — поставляет официальный дилер, неактуальный каталожный номер", "<b>Полный непрямой</b> — сторонний изготовитель, полностью совпадает по характеристикам и назначению", "<b>Условный непрямой</b> — совпадает только по ключевым характеристикам, есть ограничения", "Замена МТР в заказах — массовое обновление (ТОиР-83, курс 60); взаимозаменяемость WK — вкладка «Взаимозаменяемость»"])}
        <b>Оборотный (обменный) фонд</b>${smList(["Узлы и агрегаты, которые ремонтируют и возвращают на склад: снятый узел → восстановление → поступление восстановленной позиции", "Планировщик анализирует состояние ОФ и закрывает плановые заказы; инженер ТОиР проводит поступление"])}</div>
      <div><b>АТЗ</b> — аварийно-технический запас: неснижаемый минимум МТР на складе УО для непредвиденных отказов (ПП-07.02.05).
        <b>МТР подрядчика (УСО)</b>${smList(["В заказе — строка «ТОиР. Материалы подрядчика»; позиции подрядчик загружает массово (ТОиР-80)", "Статус и факт — по заказу ТОРО: не закрыт заказ — не закрыто и УСО", "Состав, количество и цену показывают «График · план-факт» и карточка заказа"])}
        <b>Выбор запчастей</b>${smList(["Из каталога LinkOne при создании и изменении заказа (инструкция 194_Планировщик ТОиР); в отчёте — вкладка «Каталог LinkOne»", "Сезонные материалы — в ТК и спецификациях с учётом сезонности", "Перенос МТР из заказов-доноров в заказы-получатели — ТОиР-62"])}</div></div>
      ${smSrc("регламент «Формирование и потребление оборотного фонда», методика «Учёт и использование обменного фонда», памятки ТОиР-62, ТОиР-80, ТОиР-83, «Сезонный материал», термины регламента годового планирования.")}`)}`;
}

/* ======================= 10. ТРАНЗАКЦИИ ======================= */
const SAP_TX = [
  ["Сообщения", "IW21 / IW22 / IW23", "Создать / изменить / просмотреть сообщение ТОРО"], ["Сообщения", "IW28 / IW29", "Список сообщений: в работу, присвоить заказ, создать заказ, переназначение между БЕ"],
  ["Заказы", "IW31 / IW34", "Создать заказ (без сообщения / к сообщению); планирующий завод — на первом экране"], ["Заказы", "IW32 / IW33", "Изменить / просмотреть заказ: статусы, деблокирование, ТЗКР"],
  ["Заказы", "IW38 / IW39", "Список заказов: массовые статусы, копирование, CONTROL (контроль закрытия), данные бизнес-плана, фоновый пересчёт"], ["Заказы", "ZPM_PLAN", "АРМ планировщика: годовой/месячный/недельный график, согласование, ОР"],
  ["Заказы", "ZPM_DATE_BLOCK", "Блокировки сроков заказов"], ["Заказы", "ZMM_CHREQ_MAINT", "Запросы на корректировку (ЗНК)"], ["Заказы", "ZPM_RCH", "Причины отклонения затрат от бизнес-плана"],
  ["Исполнение", "IW41", "Подтверждение трудозатрат"], ["Исполнение", "MIGO", "Выдача и списание МТР"], ["Исполнение", "ZMM_370", "Пульт по выручке: ставит ВСБЕ"],
  ["МТР", "ZMM_MRP_MAINT", "Срез ППМ (offline), сверка НВСО"], ["МТР", "MD04 / MB52", "Ситуация ППМ онлайн / складские запасы"],
  ["БДН", "IP11 / IP12", "Стратегии ТОРО"], ["БДН", "IP42 / IP02 / IP03 / IP16", "Планы ППР: создание, изменение, просмотр, список"], ["БДН", "IP10 / IP30", "Календарное планирование плана / отзыв по сроку"],
  ["БДН", "IA01–IA03 / IA11–IA13 / IA05–IA07 / IA09", "Техкарты для ЕО / для ТМ / инструкции ТОРО / список"], ["БДН", "IP17", "Позиции ППР: массовая смена ответственных"],
  ["БДО", "IL01 / IL02 / IH06 / IL05", "Технические места: создать, изменить, список, массово"], ["БДО", "IE01 / IE02 / IH08 / IE05", "Единицы оборудования: создать, изменить, список, массово"], ["БДО", "IH01", "Структура технических мест"],
  ["БДО", "IR01 / IR02 / CR05", "Рабочие места"], ["БДО", "IK01 / IK02 / IK07", "Точки измерения"], ["БДО", "IK11 / IK12 / ZPM_DOCIZM", "Документы измерения"], ["БДО", "QS41 / QS42 / OQN6", "Каталоги кодов и каталог кодов ТОРО"],
  ["Бюджет", "SAP MCB", "Бюджетные ориентиры, согласование и утверждение бюджета ППА, корректировки лимитов"],
];
function sapTx() { return smCard("Справочник транзакций", `<p>Транзакции SAP S/4HANA, упомянутые в документах ТОиР, с назначением.</p><div id="sapTx"></div>`); }
function sapTxTable() {
  const h = byId("sapTx"); if (!h) return;
  renderTable(h, { rows: SAP_TX.map(([g, t, d]) => ({ g, t, d })), sortKey: "g", sortDir: 1, limit: 100, csv: true, csvName: "sap_transactions.csv",
    cols: [{ key: "g", label: "Раздел" }, { key: "t", label: "Транзакция", cls: "mono" }, { key: "d", label: "Назначение", cls: "wrap" }] });
}

/* ======================= 11. ИСТОЧНИКИ ======================= */
function sapSrc() {
  const S = D.sapSources;
  return smCard("Документы-источники", `<p>Библиотека TOPO <span class="mono">rawdata/SAP_Description</span>: ${S ? num(S.meta.files) : "—"} документов — концептуальные дизайны
    SAP (КД ERP.13.9.2.x), нормативно-методические документы (регламенты и методики Компании, инструкции ролей), учебные курсы и памятки ТОиР.
    Тексты вкладки — выжимка из них; цифры «по данным» — из выгрузок PM-06 2022–2027.</p><input id="sapSrcQ" class="sm-q" placeholder="Поиск по названию"><div id="sapSrc"></div>`);
}
function sapSrcTable() {
  const h = byId("sapSrc"); if (!h || !D.sapSources) return;
  const all = D.sapSources.docs.map(([g, t, e, s]) => ({ g, t, e: e.toUpperCase(), s }));
  const draw = q => { const t = normText(q || ""); renderTable(h, { rows: all.filter(r => !t || normText(r.t + " " + r.g).includes(t)), sortKey: "g", sortDir: 1, limit: 200,
    cols: [{ key: "g", label: "Раздел" }, { key: "t", label: "Документ", cls: "wrap" }, { key: "e", label: "Формат" }, { key: "s", label: "Размер", numeric: true, fmt: v => num(v / 1e6, 1) + " МБ" }] }); };
  draw(""); const q = byId("sapSrcQ"); if (q) q.oninput = debounce(e => draw(e.target.value), 150);
}
